-- Add separate saved trips only; do not modify existing itineraries.
USE smart_travel_db;
SET NAMES utf8mb4;
START TRANSACTION;
SET @owner=(SELECT member_id FROM members WHERE login_id='user1' AND status='ACTIVE' AND deleted_at IS NULL);
INSERT INTO mypage_course_draft(member_id,client_id,title,region,start_date,end_date,days_json) SELECT @owner,'mypage-user1-saved-202612-1','[테스트] 울산 관광지 저장된 여행','울산','2026-12-05',DATE_ADD('2026-12-05',INTERVAL 1 DAY),JSON_ARRAY(JSON_OBJECT('date','2026-12-05','places',JSON_ARRAY((SELECT name FROM place WHERE place_id=106 AND is_active=TRUE),(SELECT name FROM place WHERE place_id=118 AND is_active=TRUE))),JSON_OBJECT('date',DATE_FORMAT(DATE_ADD('2026-12-05',INTERVAL 1 DAY),'%Y-%m-%d'),'places',JSON_ARRAY((SELECT name FROM place WHERE place_id=119 AND is_active=TRUE),(SELECT name FROM place WHERE place_id=120 AND is_active=TRUE)))) WHERE @owner IS NOT NULL AND (SELECT COUNT(*) FROM place WHERE place_id IN (106,118,119,120) AND is_active=TRUE)=4 AND NOT EXISTS(SELECT 1 FROM mypage_course_draft WHERE member_id=@owner AND client_id='mypage-user1-saved-202612-1');
INSERT INTO mypage_course_draft(member_id,client_id,title,region,start_date,end_date,days_json) SELECT @owner,'mypage-user1-saved-202612-2','[테스트] 포항 관광지 저장된 여행','포항','2026-12-12',DATE_ADD('2026-12-12',INTERVAL 1 DAY),JSON_ARRAY(JSON_OBJECT('date','2026-12-12','places',JSON_ARRAY((SELECT name FROM place WHERE place_id=9590 AND is_active=TRUE),(SELECT name FROM place WHERE place_id=9592 AND is_active=TRUE))),JSON_OBJECT('date',DATE_FORMAT(DATE_ADD('2026-12-12',INTERVAL 1 DAY),'%Y-%m-%d'),'places',JSON_ARRAY((SELECT name FROM place WHERE place_id=9595 AND is_active=TRUE),(SELECT name FROM place WHERE place_id=9600 AND is_active=TRUE)))) WHERE @owner IS NOT NULL AND (SELECT COUNT(*) FROM place WHERE place_id IN (9590,9592,9595,9600) AND is_active=TRUE)=4 AND NOT EXISTS(SELECT 1 FROM mypage_course_draft WHERE member_id=@owner AND client_id='mypage-user1-saved-202612-2');
INSERT INTO mypage_course_draft(member_id,client_id,title,region,start_date,end_date,days_json) SELECT @owner,'mypage-user1-saved-202612-3','[테스트] 여수 관광지 저장된 여행','여수','2026-12-19',DATE_ADD('2026-12-19',INTERVAL 1 DAY),JSON_ARRAY(JSON_OBJECT('date','2026-12-19','places',JSON_ARRAY((SELECT name FROM place WHERE place_id=8787 AND is_active=TRUE),(SELECT name FROM place WHERE place_id=8826 AND is_active=TRUE))),JSON_OBJECT('date',DATE_FORMAT(DATE_ADD('2026-12-19',INTERVAL 1 DAY),'%Y-%m-%d'),'places',JSON_ARRAY((SELECT name FROM place WHERE place_id=8859 AND is_active=TRUE),(SELECT name FROM place WHERE place_id=8860 AND is_active=TRUE)))) WHERE @owner IS NOT NULL AND (SELECT COUNT(*) FROM place WHERE place_id IN (8787,8826,8859,8860) AND is_active=TRUE)=4 AND NOT EXISTS(SELECT 1 FROM mypage_course_draft WHERE member_id=@owner AND client_id='mypage-user1-saved-202612-3');
COMMIT;
SELECT id,title,region,start_date,end_date,days_json FROM mypage_course_draft WHERE member_id=@owner AND client_id LIKE 'mypage-user1-saved-202612-%';
